# Illustrative Python translation of your fc program.
# Read-only — shows the shape. draw_*/play_sound/etc. are
# fantasy-console calls (fc has a built-in game engine).

mode = "play"
score = 0
px = 52
ball = {"x": 60, "y": 96, "dx": 0.65, "dy": 0 - 0.7}
bricks = []
for row in range(0, 4 + 1):
    for col in range(0, 7 + 1):
        brick = sprite
        brick["x"] = col * 16 + 1
        brick["y"] = row * 9 + 12
        bricks.append(brick)
define_sound("bounce")
define_sound("break")
define_sound("drop")

def update():
    if mode != "play":
        return
    if key_pressed("left"):
        px -= 2
    if key_pressed("right"):
        px += 2
    if px < 0:
        px = 0
    if px > 104:
        px = 104
    ball["x"] = ball["x"] + ball["dx"]
    ball["y"] = ball["y"] + ball["dy"]
    if ball["x"] < 1:
        ball["dx"] = 0 - ball["dx"]
    if ball["x"] > 124:
        ball["dx"] = 0 - ball["dx"]
    if ball["y"] < 1:
        ball["dy"] = 0 - ball["dy"]
    if ball["y"] > 114 and ball["x"] + 3 > px and ball["x"] < px + 24:
        ball["dy"] = 0 - ball["dy"]
        ball["y"] = 113
        play_sound("bounce")
    if ball["y"] > 127:
        mode = "lose"
        play_sound("drop")
    hitbrick = False
    for brick in bricks:
        if not hitbrick:
            if ball["x"] + 3 > brick["x"] and ball["x"] < brick["x"] + 14:
                if ball["y"] + 3 > brick["y"] and ball["y"] < brick["y"] + 7:
                    hitbrick = brick
    if hitbrick:
        bricks.remove(hitbrick)
        ball["dy"] = 0 - ball["dy"]
        score += 1
        play_sound("break")
    if not bricks:
        mode = "win"

def draw():
    clear_screen("black")
    for brick in bricks:
        draw_rect(brick["x"], brick["y"], 14, 7, "orange")
    draw_rect(px, 118, 24, 3, "white")
    draw_rect(ball["x"], ball["y"], 3, 3, "white")
    write_text(f"score {score}", 2, 2, "white")  # on HUD

def screen_win():  # shown while mode is "win"
    write_text("YOU WIN!", 36, 54, "yellow")  # on HUD
    write_text(f"score {score}", 38, 70, "white")  # on HUD

def screen_lose():  # shown while mode is "lose"
    write_text("GAME OVER", 32, 54, "red")  # on HUD
    write_text(f"score {score}", 38, 70, "white")  # on HUD
run_game(update, draw)

breakout.fc.js:
// Illustrative JavaScript translation of your fc program.
// Read-only — shows the shape. draw_*/play_sound/etc. are
// fantasy-console calls (fc has a built-in game engine).

let mode = "play";
let score = 0;
let px = 52;
let ball = {x: 60, y: 96, dx: 0.65, dy: 0 - 0.7};
let bricks = [];
for (let row = 0; row <= 4; row++) {
  for (let col = 0; col <= 7; col++) {
    brick = sprite;
    brick.x = col * 16 + 1;
    brick.y = row * 9 + 12;
    bricks.push(brick);
  }
}
define_sound("bounce");
define_sound("break");
define_sound("drop");

function update() {
  if (mode !== "play") {
    return;
  }
  if (key_pressed("left")) {
    px -= 2;
  }
  if (key_pressed("right")) {
    px += 2;
  }
  if (px < 0) {
    px = 0;
  }
  if (px > 104) {
    px = 104;
  }
  ball.x = ball.x + ball.dx;
  ball.y = ball.y + ball.dy;
  if (ball.x < 1) {
    ball.dx = 0 - ball.dx;
  }
  if (ball.x > 124) {
    ball.dx = 0 - ball.dx;
  }
  if (ball.y < 1) {
    ball.dy = 0 - ball.dy;
  }
  if (ball.y > 114 && ball.x + 3 > px && ball.x < px + 24) {
    ball.dy = 0 - ball.dy;
    ball.y = 113;
    play_sound("bounce");
  }
  if (ball.y > 127) {
    mode = "lose";
    play_sound("drop");
  }
  hitbrick = false;
  for (const brick of bricks) {
    if (!hitbrick) {
      if (ball.x + 3 > brick.x && ball.x < brick.x + 14) {
        if (ball.y + 3 > brick.y && ball.y < brick.y + 7) {
          hitbrick = brick;
        }
      }
    }
  }
  if (hitbrick) {
    bricks.splice(bricks.indexOf(hitbrick), 1);
    ball.dy = 0 - ball.dy;
    score += 1;
    play_sound("break");
  }
  if (!bricks) {
    mode = "win";
  }
}

function draw() {
  clear_screen("black");
  for (const brick of bricks) {
    draw_rect(brick.x, brick.y, 14, 7, "orange");
  }
  draw_rect(px, 118, 24, 3, "white");
  draw_rect(ball.x, ball.y, 3, 3, "white");
  write_text(`score ${score}`, 2, 2, "white")  // on HUD;
}

function screen_win() {  // shown while mode is "win"
  write_text("YOU WIN!", 36, 54, "yellow")  // on HUD;
  write_text(`score ${score}`, 38, 70, "white")  // on HUD;
}

function screen_lose() {  // shown while mode is "lose"
  write_text("GAME OVER", 32, 54, "red")  // on HUD;
  write_text(`score ${score}`, 38, 70, "white")  // on HUD;
}
run_game(update, draw);

