join_room("cycles", "grid")
step = 4
mode = "play"
cx = 1 + random.randint(0, 28)
cy = 1 + random.randint(0, 28)
me = {"x": 0, "y": 0, "dx": 4, "dy": 0, "alive": True, "dead": 0, "wins": 0, "claimed": False, "trail": [], "id": 0, "host": False, "clock": 0}
me["x"] = cx * 4
me["y"] = cy * 4
me["id"] = random.randint(0, 100000)
if me["x"] > 64:
    me["dx"] = 0 - step
set_time_limit(30)  # seconds
define_sound("crash")

# when the timer runs out
if timer_ended():
    mode = "over"

def update():
    amhost = True
    for peer in peers:
        if peer["id"] < me["id"]:
            amhost = False
    me["host"] = amhost
    if amhost:
        me["clock"] = timer
    else:
        for peer in peers:
            if peer["host"]:
                me["clock"] = peer["clock"]
    if mode == "play":
        if me["alive"]:
            if key_pressed("up"):
                if me["dy"] == 0:
                    me["dx"] = 0
                    me["dy"] = 0 - step
            if key_pressed("down"):
                if me["dy"] == 0:
                    me["dx"] = 0
                    me["dy"] = step
            if key_pressed("left"):
                if me["dx"] == 0:
                    me["dx"] = 0 - step
                    me["dy"] = 0
            if key_pressed("right"):
                if me["dx"] == 0:
                    me["dx"] = step
                    me["dy"] = 0

            # every 3 frames
            if frame % 3 == 0:
                me["trail"].append({"x": me["x"], "y": me["y"]})
                me["x"] = me["x"] + me["dx"]
                me["y"] = me["y"] + me["dy"]
                if me["x"] < 4 or me["x"] > 116 or me["y"] < 4 or me["y"] > 116:
                    me["alive"] = False
                for seg in me["trail"]:
                    if seg["x"] == me["x"] and seg["y"] == me["y"]:
                        me["alive"] = False
                for foe in peers:
                    if foe["x"] == me["x"] and foe["y"] == me["y"]:
                        me["alive"] = False
                    for seg in foe["trail"]:
                        if seg["x"] == me["x"] and seg["y"] == me["y"]:
                            me["alive"] = False
                if me["alive"] == False:
                    me["dead"] = 50
                    play_sound("crash")
        else:
            me["dead"] = me["dead"] - 1
            if me["dead"] <= 0:
                cx = 1 + random.randint(0, 28)
                cy = 1 + random.randint(0, 28)
                me["x"] = cx * 4
                me["y"] = cy * 4
                me["dx"] = step
                me["dy"] = 0
                if me["x"] > 64:
                    me["dx"] = 0 - step
                me["trail"] = []
                me["alive"] = True
                me["claimed"] = False
        if me["alive"]:
            if me["claimed"] == False:
                others = len(peers)
                down = 0
                for foe in peers:
                    if foe["alive"] == False:
                        down = down + 1
                if others > 0:
                    if down == others:
                        me["wins"] = me["wins"] + 1
                        me["claimed"] = True

    # every 2 frames
    if frame % 2 == 0:
        broadcast({"x": me["x"], "y": me["y"], "alive": me["alive"], "wins": me["wins"], "id": me["id"], "host": me["host"], "clock": me["clock"], "trail": me["trail"]})

def draw():
    clear_screen("black")
    for foe in peers:
        for seg in foe["trail"]:
            draw_rect(seg["x"], seg["y"], 3, 3, "red")
        draw_rect(foe["x"], foe["y"], 4, 4, "red")
    for seg in me["trail"]:
        draw_rect(seg["x"], seg["y"], 3, 3, "blue")
    if me["alive"]:
        draw_rect(me["x"], me["y"], 4, 4, "white")
    else:
        draw_rect(me["x"], me["y"], 4, 4, "red")
    others = len(peers)
    if mode == "play":
        write_text(f"wins {me.wins}", 4, 2, "white")  # on HUD
        if me["clock"] < 6:
            write_text(f"time {me.clock}", 78, 2, "red")  # on HUD
        else:
            write_text(f"time {me.clock}", 78, 2, "yellow")  # on HUD
    if mode == "over":
        best = me["wins"]
        for foe in peers:
            if foe["wins"] > best:
                best = foe["wins"]
        if me["wins"] >= best:
            write_text("TIME! you win", 28, 50, "green")  # on HUD
        else:
            write_text("TIME! you lose", 28, 50, "red")  # on HUD
        write_text(f"wins {me.wins}", 42, 62, "white")  # on HUD
run_game(update, draw)

