  ny = hy + dy;
  if (nx < 0 || nx > 120 || ny < 0 || ny > 120) {
    mode = "lose";
    play_sound("die");
    return;
  }
  for (const seg of body) {
    if (seg.x === nx && seg.y === ny) {
      mode = "lose";
    }
  }
  if (mode === "lose") {
    play_sound("die");
    return;
