// Illustrative JavaScript translation of your fc program.
// Read-only — shows the shape. draw_*/play_sound/etc. are
// fantasy-console calls (fc has a built-in game engine).

let world = {width: 128, height: 128};
let mode = "play";
let score = 0;
set_time_limit(20)  // seconds;
let player = new_sprite("centered", {image: "hero", speed: 1.5});
let coins = Array.from({length: 8}, () => new_sprite({image: "coin"}));
set_tag("coins", "pickups");  // coins are pickups
camera_follow("player");

// when the player picks up coin
if (player_picks_up("coin")) {
  score += 1;
}

// when the timer runs out
if (timer_ended()) {
  mode = "over";
}

function update() {
  if (mode === "play") {
    move_with_arrows("player");
  }
}

function draw() {
  clear_screen("dark blue");
  if (mode === "play") {
    for (const coin of coins) {
      draw_sprite(coin.x, coin.y);
    }
    draw_sprite(player.x, player.y);
    write_text(`score ${score}`, 2, 2, "white")  // on HUD;
    write_text(`time ${timer}`, 92, 2, "yellow")  // on HUD;
    if (timer < 6) {
      write_text("hurry!", 48, 2, "red")  // on HUD;
    }
  }
  if (mode === "over") {
    write_text("TIME UP!", 44, 50, "red")  // on HUD;
    write_text(`you grabbed ${score}`, 34, 64, "white")  // on HUD;
  }
}
run_game(update, draw);
